Author:     Magnus Melin <mkmelin+mozilla@iki.fi>
AuthorDate: Mon May 4 11:07:49 2026 +0000
Commit:     Magnus Melin <mkmelin+mozilla@iki.fi>
CommitDate: Mon May 4 11:07:49 2026 +0000

    Bug 2035816 - Fix [ASan perma] LeakSanitizer leak at PL_strndup, MimeInlineTextHTML_parse_line, MimeInlineTextHTMLParsed_parse_eof, MimeContainer_parse_eof. r=jtracey



    `./mach test comm/mail/base/test/browser/browser_feedBodyDisplay.js` with an ASan build shows leak without this patch

    Differential Revision: https://phabricator.services.mozilla.com/D297328

diff --git a/mailnews/mime/src/mimethtm.cpp b/mailnews/mime/src/mimethtm.cpp
index f934d70d3b7..820b3ab4a7b 100644
--- a/mailnews/mime/src/mimethtm.cpp
+++ b/mailnews/mime/src/mimethtm.cpp
@@ -21,16 +21,27 @@ MimeDefClass(MimeInlineTextHTML, MimeInlineTextHTMLClass,
 static int MimeInlineTextHTML_parse_line(const char*, int32_t, MimeObject*);
 static int MimeInlineTextHTML_parse_eof(MimeObject*, bool);
 static int MimeInlineTextHTML_parse_begin(MimeObject* obj);
+static void MimeInlineTextHTML_finalize(MimeObject*);

 static int MimeInlineTextHTMLClassInitialize(MimeObjectClass* oclass) {
   PR_ASSERT(!oclass->class_initialized);
   oclass->parse_begin = MimeInlineTextHTML_parse_begin;
   oclass->parse_line = MimeInlineTextHTML_parse_line;
   oclass->parse_eof = MimeInlineTextHTML_parse_eof;
+  oclass->finalize = MimeInlineTextHTML_finalize;

   return 0;
 }

+static void MimeInlineTextHTML_finalize(MimeObject* obj) {
+  MimeInlineTextHTML* textHTML = (MimeInlineTextHTML*)obj;
+
+  PR_FREEIF(textHTML->charset);
+  textHTML->charset = nullptr;
+
+  ((MimeObjectClass*)&MIME_SUPERCLASS)->finalize(obj);
+}
+
 static int MimeInlineTextHTML_parse_begin(MimeObject* obj) {
   int status = ((MimeObjectClass*)&mimeLeafClass)->parse_begin(obj);
   if (status < 0) return status;
@@ -146,11 +157,8 @@ static int MimeInlineTextHTML_parse_line(const char* line, int32_t length,

 static int MimeInlineTextHTML_parse_eof(MimeObject* obj, bool abort_p) {
   int status;
-  MimeInlineTextHTML* textHTML = (MimeInlineTextHTML*)obj;
   if (obj->closed_p) return 0;

-  PR_FREEIF(textHTML->charset);
-
   /* Run parent method first, to flush out any buffered data. */
   status = ((MimeObjectClass*)&MIME_SUPERCLASS)->parse_eof(obj, abort_p);
   if (status < 0) return status;
